import sys


def task_results(sessions):
    """sessions: (participant, task, success|fail|abandon, seconds). Per task, sorted by task: the success rate as a whole percent rounded down, and the median time of the SUCCESSFUL attempts (the mean of the two middle values for an even count), or None if nobody succeeded. Return [(task, pct, median)]."""
    attempts, times = {}, {}
    for _, task, outcome, seconds in sessions:
        attempts[task] = attempts.get(task, 0) + 1
        if outcome == "success":
            times.setdefault(task, []).append(seconds)
    out = []
    for task in sorted(attempts):
        ok = sorted(times.get(task, []))
        median = None
        if ok:
            mid = len(ok) // 2
            median = ok[mid] if len(ok) % 2 else (ok[mid - 1] + ok[mid]) / 2
        out.append((task, 100 * len(ok) // attempts[task], median))
    return out


def main():
    data = sys.stdin.read().split("\n")
    n = int(data[0])
    sessions = []
    for i in range(n):
        participant, task, outcome, seconds = data[1 + i].split()
        sessions.append((participant, task, outcome, int(seconds)))
    for task, pct, median in task_results(sessions):
        print(task, f"{pct}%", "-" if median is None else format(median, ".1f"))


main()

import sys


def card_clusters(groups, participants, threshold):
    """groups: (participant, [cards in one pile]). Two cards are linked when at least `threshold` percent of participants put them in the same pile. Clusters are the connected groups of linked cards (a card with no links is a cluster on its own). Return clusters, each sorted, ordered by their first card."""
    together = {}                                  # (card a, card b) -> participants who grouped them
    cards = set()
    for participant, pile in groups:
        cards.update(pile)
        for i, a in enumerate(pile):
            for b in pile[i + 1:]:
                together.setdefault(tuple(sorted((a, b))), set()).add(participant)
    links = {c: [] for c in cards}
    for (a, b), people in together.items():
        if len(people) * 100 >= threshold * participants:
            links[a].append(b)
            links[b].append(a)
    seen, clusters = set(), []
    for card in sorted(cards):                      # connected components by depth-first search
        if card in seen:
            continue
        stack, group = [card], []
        seen.add(card)
        while stack:
            c = stack.pop()
            group.append(c)
            for nxt in links[c]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        clusters.append(sorted(group))
    return clusters


def main():
    data = sys.stdin.read().split("\n")
    participants, threshold = map(int, data[0].split())
    n = int(data[1])
    groups = []
    for i in range(n):
        participant, _, cards = data[2 + i].split()
        groups.append((participant, cards.split(",")))
    for cluster in card_clusters(groups, participants, threshold):
        print(", ".join(cluster))


